    48  export default function <TProps extends WithReportAndReportActionOrNotFoundProps, TRef>(
    49      WrappedComponent: ComponentType<TProps & RefAttributes<TRef>>,
    50  ): ComponentType<Omit<TProps & RefAttributes<TRef>, keyof OnyxProps>> {
    51      function WithReportOrNotFound(props: TProps, ref: ForwardedRef<TRef>) {
    52          const getReportAction = useCallback(() => {
    53              let reportAction: OnyxEntry<OnyxTypes.ReportAction> = props.reportActions?.[`${props.route.params.reportActionID}`];
    54
    55              // Handle threads if needed
    56              if (!reportAction?.reportActionID) {
    57                  reportAction = props?.parentReportAction ?? undefined;
    58              }
    59
    60              return reportAction;
    61          }, [props.reportActions, props.route.params.reportActionID, props.parentReportAction]);
    62
    63          const reportAction = getReportAction();
    64
    65          const {shouldUseNarrowLayout} = useResponsiveLayout();
    66
    67          // For small screen, we don't call openReport API when we go to a sub report page by deeplink
    68          // So we need to call openReport here for small screen
    69          useEffect(() => {
    70              if (!shouldUseNarrowLayout || (!isEmptyObject(props.report) && !isEmptyObject(reportAction))) {
    71                  return;
    72              }
    73              Report.openReport(props.route.params.reportID);
    74              // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    75          }, [shouldUseNarrowLayout, props.route.params.reportID]);
    76
    77          // Perform all the loading checks
    78          const isLoadingReport = props.isLoadingReportData && !props.report?.reportID;
    79          const isLoadingReportAction = isEmptyObject(props.reportActions) || (props.reportMetadata?.isLoadingInitialReportActions && isEmptyObject(getReportAction()));
    80          const shouldHideReport = !isLoadingReport && (!props.report?.reportID || !ReportUtils.canAccessReport(props.report, props.policies, props.betas));
    81
    82          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
    83          if ((isLoadingReport || isLoadingReportAction) && !shouldHideReport) {
    84              return <FullscreenLoadingIndicator />;
    85          }
    86
    87          // Perform the access/not found checks
    88          // Be sure to avoid showing the not-found page while the parent report actions are still being read from Onyx. The parentReportAction will be undefined while it's being read from Onyx
