   123          },
   124          reportActions: {
   125              key: ({route}) => `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${route.params.reportID}`,
   126              canEvict: false,
   127          },
   128          parentReportAction: {
   129              key: ({report}) => `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${report ? report.parentReportID : 0}`,
   130              selector: (parentReportActions: OnyxEntry<OnyxTypes.ReportActions>, props?: WithOnyxState<OnyxProps>): NonNullable<OnyxEntry<OnyxTypes.ReportAction>> | null => {
   131                  const parentReportActionID = props?.report?.parentReportActionID;
   132                  if (!parentReportActionID) {
   133                      return null;
